function formatDateType(dateInput) {
    const date = new Date(dateInput);
    if (isNaN(date)) {
        return 'Invalid Date';  
    }

    const day = String(date.getDate()).padStart(2, '0'); 
    const month = String(date.getMonth() + 1).padStart(2, '0'); 
    const year = date.getFullYear(); 

    return `${day}.${month}.${year}`; 
}
return formatDateType

const date = new Date()

const day = date.getDate();
const month = date.getMonth() + 1; 
const year = date.getFullYear(); 

const formattedDate = `${year < 10 ? '0' : ''}${year}.${month < 10 ? '0' : ''}${month}.${day < 10 ? '0' : ''}${day}`;
return formattedDate;

function findCode(code) {
    const allData = getCalculationRules?.data?.data?.ExpenseRule; 
    const allCodes = allData.map((item) => item.code);

    if (code === '' || code === undefined) {
        return `${window.lowcoder.translate('lowcoder:expense_calculation_rule.expense_calculation_rule_modal.is_code_unique_first', 'The \'Rule Code\' field is required.')}`;
    }
    console.log(currentRuleCode.value)
    const lowerCasedCodes = allCodes.map(item => item?.toLowerCase());
    if (lowerCasedCodes.includes(code.toLowerCase())) {
        return `${window.lowcoder.translate('lowcoder:expense_calculation_rule.expense_calculation_rule_modal.is_code_unique_second', 'This code already exists')}`;
    }

    return ''; 
}
return findCode

function validateFunction(receivedValue) {
    const regexTest = /^\d{1,3}(\.\d{3})*,\d{2}$/;
    if (!regexTest.test(receivedValue)) {
        return "The 'Amount' field is invalid. Please use 2 decimals";
    }
    return "";
}
return validateFunction

function reorderCurrencies(currencies) {
const topCurrencies = ["EUR", "USD", "RON"];
const reorderedCurrencies = currencies
  .filter(currency => topCurrencies.includes(currency.code))
  .sort((a, b) => topCurrencies.indexOf(a.code) - topCurrencies.indexOf(b.code))
  .concat(currencies.filter(currency => !topCurrencies.includes(currency.code)));
  return reorderedCurrencies
}
return reorderCurrencies;

